def _compile_removal_pattern() -> re.Pattern[str]:
    parts: list[str] = []
    for item in _REMOVAL_RANGES.split(","):
        start_text, separator, end_text = item.partition("-")
        start = int(start_text, 16)
        end = int(end_text, 16) if separator else start
        part = f"\\U{start:08X}"
        if end != start:
            part += f"-\\U{end:08X}"
        parts.append(part)
    return re.compile("[" + "".join(parts) + "]")


GITHUB_SLUG_REMOVAL_RE = _compile_removal_pattern()
